### ① Concept Explanation

**Retrieval strategies** determine how an agent fetches relevant memory given the current context. The main strategies are: **Dense retrieval** (embedding similarity — finds semantically similar content); **Sparse retrieval** (BM25/TF-IDF keyword matching — finds exact keyword matches); **Hybrid retrieval** (combines dense + sparse for best recall); **MMR** (Maximum Marginal Relevance — retrieves diverse, non-redundant results); **Time-weighted retrieval** (boosts recent memories); and **Metadata-filtered retrieval** (narrows the search space by user ID, topic, date, etc.). Production memory systems almost always use **hybrid retrieval** because purely semantic search misses exact matches (e.g., searching for "AWS S3 bucket" might miss if stored as "Amazon S3 object storage") and purely keyword search misses semantic variants.

### ② Implementation

```python
from rank_bm25 import BM25Okapi  # bm25 0.0.2+

class HybridRetriever:
    """
    Combines dense (embedding) + sparse (BM25) retrieval.
    Uses Reciprocal Rank Fusion (RRF) to merge result lists.
    """

    def __init__(self, dense_store: VectorMemory):
        self.dense = dense_store
        self._bm25: BM25Okapi | None = None
        self._bm25_records: list[MemoryRecord] = []

    def _rebuild_bm25(self) -> None:
        """Rebuild BM25 index when new records added."""
        self._bm25_records = list(self.dense.records)
        tokenized = [rec.content.lower().split() for rec in self._bm25_records]
        if tokenized:
            self._bm25 = BM25Okapi(tokenized)

    def search(self, query: str, top_k: int = 5) -> list[MemoryRecord]:
        """Hybrid search using RRF fusion."""
        if not self.dense.records:
            return []

        # Dense retrieval ranks
        dense_results = self.dense.search(query, top_k=top_k * 2)
        dense_ranks = {r.id: i + 1 for i, r in enumerate(dense_results)}

        # Sparse retrieval ranks
        if self._bm25 is None or len(self._bm25_records) != len(self.dense.records):
            self._rebuild_bm25()

        if self._bm25 and self._bm25_records:
            bm25_scores = self._bm25.get_scores(query.lower().split())
            bm25_ranked = sorted(
                enumerate(self._bm25_records),
                key=lambda x: -bm25_scores[x[0]],
            )
            sparse_ranks = {rec.id: i + 1 for i, (_, rec) in enumerate(bm25_ranked[:top_k * 2])}
        else:
            sparse_ranks = {}

        # Reciprocal Rank Fusion
        rrf_scores: dict[str, float] = {}
        k = 60  # RRF constant

        for rec in self.dense.records:
            score = 0.0
            if rec.id in dense_ranks:
                score += 1.0 / (k + dense_ranks[rec.id])
            if rec.id in sparse_ranks:
                score += 1.0 / (k + sparse_ranks[rec.id])
            if score > 0:
                rrf_scores[rec.id] = score

        # Sort by RRF score and return top_k
        sorted_ids = sorted(rrf_scores, key=lambda x: -rrf_scores[x])[:top_k]
        record_map = {r.id: r for r in self.dense.records}
        return [record_map[rid] for rid in sorted_ids if rid in record_map]

class MMRRetriever:
    """Maximum Marginal Relevance — retrieves diverse, non-redundant results."""

    def search(
        self,
        query_vec: np.ndarray,
        candidates: list[tuple[np.ndarray, MemoryRecord]],
        top_k: int = 5,
        lambda_param: float = 0.5,
    ) -> list[MemoryRecord]:
        """
        MMR selects results that are relevant to query but dissimilar to each other.
        lambda_param: 0 = max diversity, 1 = max relevance
        """
        selected: list[MemoryRecord] = []
        remaining = list(candidates)

        while len(selected) < top_k and remaining:
            # Score each candidate: lambda * relevance - (1-lambda) * max_similarity_to_selected
            best_score = -float("inf")
            best_candidate = None
            best_idx = -1

            for i, (vec, record) in enumerate(remaining):
                relevance = float(np.dot(query_vec, vec))

                if selected:
                    selected_vecs = np.array([v for v, _ in candidates if _ in selected])
                    sim_to_selected = float(np.max(selected_vecs @ vec)) if len(selected_vecs) > 0 else 0.0
                else:
                    sim_to_selected = 0.0

                score = lambda_param * relevance - (1 - lambda_param) * sim_to_selected

                if score > best_score:
                    best_score = score
                    best_candidate = record
                    best_idx = i

            if best_candidate:
                selected.append(best_candidate)
                remaining.pop(best_idx)

        return selected
